SELECT CASE WHEN unit_price >= 420 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END AS unit_price_bucket, ROUND(STDDEV(unit_price), 2) AS stddev_unit_price, SUM(unit_price) AS total_unit_price FROM order_items WHERE unit_price BETWEEN 100 AND 170 GROUP BY CASE WHEN unit_price >= 420 THEN 'high' WHEN unit_price >= 140 THEN 'mid' ELSE 'low' END ORDER BY stddev_unit_price DESC, unit_price_bucket LIMIT 20
